# Datos estructurales (los 7 procesos y su grafo de estados/transiciones): única fuente
# de verdad en app/reference_data.py (también la usan las pruebas, que no pasan por
# Alembic). Ver docs/PROCESOS.md.

def _seed_processes():
    processes_t = sa.table("processes", sa.column("id", sa.Integer), sa.column("code", sa.String),
                            sa.column("name", sa.String), sa.column("ticket_type", sa.String))
    states_t = sa.table("process_states", sa.column("id", sa.Integer), sa.column("process_id", sa.Integer),
                         sa.column("code", sa.String), sa.column("name", sa.String),
                         sa.column("is_initial", sa.Boolean), sa.column("is_final", sa.Boolean))
    trans_t = sa.table("process_transitions", sa.column("id", sa.Integer), sa.column("process_id", sa.Integer),
                        sa.column("from_code", sa.String), sa.column("to_code", sa.String),
                        sa.column("action", sa.String), sa.column("required_perm", sa.String))

    conn = op.get_bind()
    next_pid, next_sid, next_tid = 1, 1, 1
    for code, name, ticket_type in PROCESSES:
        conn.execute(processes_t.insert().values(id=next_pid, code=code, name=name, ticket_type=ticket_type))
        for scode, sname, is_initial, is_final in STATES[code]:
            conn.execute(states_t.insert().values(id=next_sid, process_id=next_pid, code=scode, name=sname,
                                                   is_initial=is_initial, is_final=is_final))
            next_sid += 1
        for frm, to, action, perm in TRANSITIONS[code]:
            conn.execute(trans_t.insert().values(id=next_tid, process_id=next_pid, from_code=frm, to_code=to,
                                                  action=action, required_perm=perm))
            next_tid += 1
        next_pid += 1


# Jerarquía de clasificación de CI y ubicaciones: única fuente de verdad en
# app/reference_data.py. Ver docs/MODELO.md.


def _seed_cmdb_catalogs():
    import datetime
    now = datetime.datetime(2026, 10, 29)
    classes_t = sa.table("ci_classes", sa.column("id", sa.Integer), sa.column("code", sa.String),
                          sa.column("name", sa.String), sa.column("parent_id", sa.Integer),
                          sa.column("is_active", sa.Boolean), sa.column("requires_ip", sa.Boolean),
                          sa.column("created_at", sa.DateTime), sa.column("updated_at", sa.DateTime))
    locations_t = sa.table("locations", sa.column("id", sa.Integer), sa.column("code", sa.String),
                            sa.column("name", sa.String), sa.column("is_active", sa.Boolean),
                            sa.column("created_at", sa.DateTime), sa.column("updated_at", sa.DateTime))
    conn = op.get_bind()
    ids_by_code = {}
    next_id = 1
    for code, name, parent_code, requires_ip in CI_CLASSES:
        parent_id = ids_by_code.get(parent_code)
        conn.execute(classes_t.insert().values(id=next_id, code=code, name=name, parent_id=parent_id,
                                                is_active=True, requires_ip=requires_ip,
                                                created_at=now, updated_at=now))
        ids_by_code[code] = next_id
        next_id += 1
    for i, (code, name) in enumerate(LOCATIONS, start=1):
        conn.execute(locations_t.insert().values(id=i, code=code, name=name, is_active=True,
                                                  created_at=now, updated_at=now))


